(5599312, 811910, 87808, '<td valign="top">Capital V in Vicar</td>', 'Capital V in Vicar', '2009-08-05 01:38:53.000000', NULL, 1),
(5599361, 810908, 49220, '<td valign="top">Good picture, but where''s the square?</td>', 'Good picture, but where''s the square?', '2009-08-05 01:57:42.000000', NULL, 1),
(5599379, 811955, 49220, '<td valign="top">I like this shot, but it took me a while to figure out what it was.</td>', 'I like this shot, but it took me a while to figure out what it was.', '2009-08-05 02:00:30.000000', NULL, 1),
(5599380, 811849, 49220, '<td valign="top">Good idea, but the depth of field almost seems too narrow for me.  Would be nice if one of the squares was fully in focus.  I do like the choice to tilt the image.</td>', 'Good idea, but the depth of field almost seems too narrow for me.  Would be nice if one of the squares was fully in focus.  I do like the choice to tilt the image.', '2009-08-05 02:00:34.000000', NULL, 1),
(5599381, 811910, 49220, '<td valign="top">Not sure I get the title, but a good picture.</td>', 'Not sure I get the title, but a good picture.', '2009-08-05 02:00:43.000000', NULL, 1),
(5599382, 811935, 49220, '<td valign="top">I love the use of color.  Pushing the contrast a little too far, but still ok for me.</td>', 'I love the use of color.  Pushing the contrast a little too far, but still ok for me.', '2009-08-05 02:00:46.000000', NULL, 1),
(5599386, 812032, 49220, '<td valign="top">I get the idea, but I think this doesn''t really meet the square idea (in terms of catching it in the image).  I do like the picture though.</td>', 'I get the idea, but I think this doesn''t really meet the square idea (in terms of catching it in the image).  I do like the picture though.', '2009-08-05 02:02:09.000000', NULL, 1),
(5599387, 812000, 49220, '<td valign="top">Great idea.  It''s a shame the lower hand is a bit blurry.</td>', 'Great idea.  It''s a shame the lower hand is a bit blurry.', '2009-08-05 02:02:39.000000', NULL, 1),
(5599388, 811896, 49220, '<td valign="top">Great colors, but a little bit flat on the lighting.</td>', 'Great colors, but a little bit flat on the lighting.', '2009-08-05 02:02:42.000000', NULL, 1),
(5599389, 811943, 49220, '<td valign="top">I like the background.  It seems like this image is either off on the white balance, or if that was an intentional color filter you are going for, I might have pushed the color even further so it was an apparent choice.</td>', 'I like the background.  It seems like this image is either off on the white balance, or if that was an intentional color filter you are going for, I might have pushed the color even further so it was an apparent choice.', '2009-08-05 02:02:48.000000', NULL, 1),
(5599390, 811854, 49220, '<td valign="top">Almost seems a bit over-exposed to me, but a great angle and set up.</td>', 'Almost seems a bit over-exposed to me, but a great angle and set up.', '2009-08-05 02:03:10.000000', NULL, 1),
(5599391, 811944, 49220, '<td valign="top">Got a good little laugh on this one.</td>', 'Got a good little laugh on this one.', '2009-08-05 02:03:24.000000', NULL, 1),
(5599393, 810662, 49220, '<td valign="top">A bit over contrasted for my taste, and with the crop so narrow, it would have been nice to have a larger depth of field so that the exterior was more in focus.</td>', 'A bit over contrasted for my taste, and with the crop so narrow, it would have been nice to have a larger depth of field so that the exterior was more in focus.', '2009-08-05 02:04:53.000000', NULL, 1),
(5599394, 811959, 49220, '<td valign="top">Great shot with the color overlay on the background image.  It''s a shame that nothing was more square shaped for this challenge.</td>', 'Great shot with the color overlay on the background image.  It''s a shame that nothing was more square shaped for this challenge.', '2009-08-05 02:04:55.000000', NULL, 1),
(5599395, 812031, 49220, '<td valign="top">Nice macro shot.  I would personally like it more if more of the foreground crystals were in sharper focus (i.e., a ittle bit more depth of field)</td>', 'Nice macro shot.  I would personally like it more if more of the foreground crystals were in sharper focus (i.e., a ittle bit more depth of field)', '2009-08-05 02:04:58.000000', NULL, 1),
(5599396, 810740, 49220, '<td valign="top">I love the math jokes in this challenge.  Good concept, but a bit out of focus on the dice and plant, which I assumed are the main focus.</td>', 'I love the math jokes in this challenge.  Good concept, but a bit out of focus on the dice and plant, which I assumed are the main focus.', '2009-08-05 02:05:01.000000', NULL, 1),
(5599397, 812006, 49220, '<td valign="top">I bit over-saturated and/or over-contrasted, but nice idea.</td>', 'I bit over-saturated and/or over-contrasted, but nice idea.', '2009-08-05 02:05:09.000000', NULL, 1),
(5599398, 811404, 49220, '<td valign="top">I like the math pun, but the picture seems a little bit dull.</td>', 'I like the math pun, but the picture seems a little bit dull.', '2009-08-05 02:05:11.000000', NULL, 1),
(5599400, 811951, 49220, '<td valign="top">Nice perspective, but seems a bit dull.  I would have been nice if the sky had some interest.</td>', 'Nice perspective, but seems a bit dull.  I would have been nice if the sky had some interest.', '2009-08-05 02:06:01.000000', NULL, 1),
(5599401, 811349, 49220, '<td valign="top">I love the image.  I think it is really pushing it for a square, although I can see what you are thinking.</td>', 'I love the image.  I think it is really pushing it for a square, although I can see what you are thinking.', '2009-08-05 02:06:07.000000', NULL, 1),
(5599402, 811865, 49220, '<td valign="top">A bit busy for me.  It would be a great poster or advertisement, but it seems a bit bright and flat (both perspective and lighting) for a photograph.</td>', 'A bit busy for me.  It would be a great poster or advertisement, but it seems a bit bright and flat (both perspective and lighting) for a photograph.', '2009-08-05 02:06:35.000000', NULL, 1),
(5599403, 811662, 49220, '<td valign="top">Too contrasted for my taste, but nice idea.</td>', 'Too contrasted for my taste, but nice idea.', '2009-08-05 02:07:01.000000', NULL, 1),
(5599404, 811529, 49220, '<td valign="top">I think I must be missing something...</td>', 'I think I must be missing something...', '2009-08-05 02:07:04.000000', NULL, 1),
