(5599413, 811716, 49220, '<td valign="top">I really like the perspective, lighting, and that you were fortunate enough to have an interesting sky.</td>', 'I really like the perspective, lighting, and that you were fortunate enough to have an interesting sky.', '2009-08-05 02:12:42.000000', NULL, 1),
(5599414, 811843, 49220, '<td valign="top">I love the simple but effective lighting and texture in this shot.  I like your choice of location for the main square/focus.  Great find for this challenge.</td>', 'I love the simple but effective lighting and texture in this shot.  I like your choice of location for the main square/focus.  Great find for this challenge.', '2009-08-05 02:12:46.000000', NULL, 1),
(5599415, 811913, 49220, '<td valign="top">Great shot.  I like the humor, and the way it is uneven and yet almost uniform.</td>', 'Great shot.  I like the humor, and the way it is uneven and yet almost uniform.', '2009-08-05 02:12:50.000000', NULL, 1),
(5599416, 811750, 49220, '<td valign="top">Nice simplicity and elegance to this shot.  I like the way the one stands out from the many.</td>', 'Nice simplicity and elegance to this shot.  I like the way the one stands out from the many.', '2009-08-05 02:12:52.000000', NULL, 1),
