(5607023, 811865, 100804, '<td valign="top">Nice and bright - bet you felt sick later that day.</td>', 'Nice and bright - bet you felt sick later that day.', '2009-08-11 03:51:48.000000', NULL, 1),
(5607024, 811061, 100804, '<td valign="top">Creepy but cool - I like it... wonder what the negative looks like!</td>', 'Creepy but cool - I like it... wonder what the negative looks like!', '2009-08-11 03:52:24.000000', NULL, 1),
(5607026, 811876, 100804, '<td valign="top">Really like the idea.  Perhaps it should be a square picture too.</td>', 'Really like the idea.  Perhaps it should be a square picture too.', '2009-08-11 03:52:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5607027, 812050, 100804, '<td valign="top">Really nice capture and cool lighting</td>', 'Really nice capture and cool lighting', '2009-08-11 03:53:43.000000', NULL, 1),
(5607028, 811753, 100804, '<td valign="top">Nice but seems a bit flat for some reason - sorry I''m not talented enough to give any suggestions!</td>', 'Nice but seems a bit flat for some reason - sorry I''m not talented enough to give any suggestions!', '2009-08-11 03:54:35.000000', NULL, 1),
(5607030, 811512, 100804, '<td valign="top">Nice, though I feel it needs brightening up.  Did you de-saturate it too much?</td>', 'Nice, though I feel it needs brightening up.  Did you de-saturate it too much?', '2009-08-11 03:55:27.000000', NULL, 1),
(5607031, 811750, 100804, '<td valign="top">Nicely done - needs to be totally clean and aligned.  Do you have a shot that is fully in focus?</td>', 'Nicely done - needs to be totally clean and aligned.  Do you have a shot that is fully in focus?', '2009-08-11 03:56:31.000000', NULL, 1),
(5607032, 811910, 100804, '<td valign="top">Very clever, nicely done.</td>', 'Very clever, nicely done.', '2009-08-11 03:56:52.000000', NULL, 1),
(5607033, 811529, 100804, '<td valign="top">Feels like its smiling at me... with a lone tooth sticking out!</td>', 'Feels like its smiling at me... with a lone tooth sticking out!', '2009-08-11 03:57:58.000000', NULL, 1),
(5607035, 812052, 100804, '<td valign="top">Nicely done - did you cheat?  Like the fact that you''ve rotated the shot, it adds and extra dimension.</td>', 'Nicely done - did you cheat?  Like the fact that you''ve rotated the shot, it adds and extra dimension.', '2009-08-11 04:00:03.000000', NULL, 1),
(5607199, 811944, 61679, '<td valign="top">Back to comment:  The lighting and the composition of this image is extremely well done.  However, the main subject of this photo is the frog and not a square.</td>', 'Back to comment:  The lighting and the composition of this image is extremely well done.  However, the main subject of this photo is the frog and not a square.', '2009-08-11 09:53:22.000000', NULL, 1),
(5607209, 811693, 61679, '<td valign="top">Back to comment: This image has an optical illusion aspect to it that required an extra second or two to see the squares for what they are.  Once I saw it, the illusion went away and I could not see again as I did for the very first time.  True amazing and worthy of a 10.  Hope to see it on the front page.</td>', 'Back to comment: This image has an optical illusion aspect to it that required an extra second or two to see the squares for what they are.  Once I saw it, the illusion went away and I could not see again as I did for the very first time.  True amazing and worthy of a 10.  Hope to see it on the front page.', '2009-08-11 10:07:57.000000', NULL, 1),
(5607428, 811693, 18799, '<td valign="top">My favorite of the challege 10</td>', 'My favorite of the challege 10', '2009-08-11 13:01:26.000000', NULL, 1),
(5607459, 812052, 76712, '<td valign="top">i had a photo just like this, very good :D</td>', 'i had a photo just like this, very good :D', '2009-08-11 13:22:24.000000', NULL, 1),
(5607478, 811826, 2780, '<td valign="top">I wouldn''t say the main subject was square-shaped here, sorry.</td>', 'I wouldn''t say the main subject was square-shaped here, sorry.', '2009-08-11 13:37:14.000000', NULL, 1),
(5607479, 811693, 2780, '<td valign="top">I like the simplicity and the shades, but I find the border a distraction from the otherwise clean appeal of the photo.</td>', 'I like the simplicity and the shades, but I find the border a distraction from the otherwise clean appeal of the photo.', '2009-08-11 13:38:04.000000', NULL, 1),
(5607481, 811935, 106349, '<td valign="top">Beautiful colors! Love the reflection in the window.</td>', 'Beautiful colors! Love the reflection in the window.', '2009-08-11 13:39:15.000000', NULL, 1),
(5607482, 811999, 106349, '<td valign="top">Nice tie...</td>', 'Nice tie...', '2009-08-11 13:39:47.000000', NULL, 1),
(5607485, 810740, 2780, '<td valign="top">Clever idea, but let down by the lighting unfortunately. It''s a bit harsh and illuminates the background too much. Maybe try softening it with some paper over the source and moving it more to one side?</td>', 'Clever idea, but let down by the lighting unfortunately. It''s a bit harsh and illuminates the background too much. Maybe try softening it with some paper over the source and moving it more to one side?', '2009-08-11 13:41:54.000000', NULL, 1),
(5607486, 811877, 2780, '<td valign="top">I like the simplicity</td>', 'I like the simplicity', '2009-08-11 13:43:06.000000', NULL, 1),
(5607487, 811512, 2780, '<td valign="top">I love the photo, but it''s not a square. In a free study I''d give it a 9</td>', 'I love the photo, but it''s not a square. In a free study I''d give it a 9', '2009-08-11 13:43:54.000000', NULL, 1),
(5607489, 812013, 2780, '<td valign="top">The main subject should be square, but I''d call the cow here the main subject rather than the (arguably) square nose, sorry. I also don''t care for the over-processed look.</td>', 'The main subject should be square, but I''d call the cow here the main subject rather than the (arguably) square nose, sorry. I also don''t care for the over-processed look.', '2009-08-11 13:45:31.000000', NULL, 1),
(5607491, 810738, 2780, '<td valign="top">Square bokeh, square cube puzzle, very nice! I wish it wasn''t touching the frame at the bottom but still my highest rated of the challenge.</td>', 'Square bokeh, square cube puzzle, very nice! I wish it wasn''t touching the frame at the bottom but still my highest rated of the challenge.', '2009-08-11 13:46:17.000000', NULL, 1),
(5607544, 811826, 57447, '<td valign="top">Cute!</td>', 'Cute!', '2009-08-11 15:11:27.000000', NULL, 1),
(5607560, 811975, 89116, '<td valign="top">I love the subject matter.  The old door is gorgeous but I feel like the framing should be centered.  I know you''re probably trying the follow the rule of thirds but for me, sometimes it needs to be broken.  Having the box and the railing only on one side really makes me focus on them for some reason.</td>', 'I love the subject matter.  The old door is gorgeous but I feel like the framing should be centered.  I know you''re probably trying the follow the rule of thirds but for me, sometimes it needs to be broken.  Having the box and the railing only on one side really makes me focus on them for some reason.', '2009-08-11 15:41:58.000000', NULL, 1),
(5607561, 811952, 89116, '<td valign="top">Would''ve loved to see this in black in white so the shapes pop out more.  I tend to focus on the white paper stapled to the wood instead of the fantastic shapes.</td>', 'Would''ve loved to see this in black in white so the shapes pop out more.  I tend to focus on the white paper stapled to the wood instead of the fantastic shapes.', '2009-08-11 15:43:36.000000', NULL, 1),
(5607562, 811115, 89116, '<td valign="top">The light seems harsh and the colors seem bland to me (most likely due to the harsh lighting).  I do really like the composition though especially with the break and the crumbles.</td>', 'The light seems harsh and the colors seem bland to me (most likely due to the harsh lighting).  I do really like the composition though especially with the break and the crumbles.', '2009-08-11 15:44:58.000000', NULL, 1),
(5607563, 811815, 89116, '<td valign="top">Absolutely stunning!  I love the old textures of the chipping paint/wood and the torn curtains.  Excellent choice for a black and white image!</td>', 'Absolutely stunning!  I love the old textures of the chipping paint/wood and the torn curtains.  Excellent choice for a black and white image!', '2009-08-11 15:46:08.000000', NULL, 1),
(5607564, 812043, 89116, '<td valign="top">If it was black and white I''d focus more on the shapes in the image instead of the colors which in my opinion don''t seem that great.  I do really like the shapes and the man''s legs sitting there but I feel like there is too much space to the left especially with the overblown areas in the top-left corner.  It''s hard to expose such a contrasty scene.  5.</td>', 'If it was black and white I''d focus more on the shapes in the image instead of the colors which in my opinion don''t seem that great.  I do really like the shapes and the man''s legs sitting there but I feel like there is too much space to the left especially with the overblown areas in the top-left corner.  It''s hard to expose such a contrasty scene.  5.', '2009-08-11 15:48:28.000000', NULL, 1),
(5607566, 811876, 89116, '<td valign="top">I love the lighting in the shot and the composition is fantastic!  Great Shot!</td>', 'I love the lighting in the shot and the composition is fantastic!  Great Shot!', '2009-08-11 15:49:54.000000', NULL, 1),
(5607568, 810662, 89116, '<td valign="top">I really like the blandness and depressed mood to the shot but I feel like the composition and framing is too limited.  I feel like I need to see more to the edges.  I do love the colors though! 6.</td>', 'I really like the blandness and depressed mood to the shot but I feel like the composition and framing is too limited.  I feel like I need to see more to the edges.  I do love the colors though! 6.', '2009-08-11 15:51:13.000000', NULL, 1),
(5607570, 811877, 89116, '<td valign="top">Wow.  I absolutly enjoy looking at this photo.  The framing and the pieces missing of the clock and how everything is completely black or completely white is amazing.  Great Shot, I would not change a thing!</td>', 'Wow.  I absolutly enjoy looking at this photo.  The framing and the pieces missing of the clock and how everything is completely black or completely white is amazing.  Great Shot, I would not change a thing!', '2009-08-11 15:53:37.000000', NULL, 1),
(5607787, 811910, 103004, '<td valign="top">what a great idea!10</td>', 'what a great idea!10', '2009-08-11 19:23:54.000000', NULL, 1),
(5607788, 812052, 103004, '<td valign="top">great idea!very nice</td>', 'great idea!very nice', '2009-08-11 19:24:02.000000', NULL, 1),
(5607906, 810738, 96729, '<td valign="top">I like the square bokeh, and I think the subject is cool, but sort of an odd composition . . .</td>', 'I like the square bokeh, and I think the subject is cool, but sort of an odd composition . . .', '2009-08-11 20:53:39.000000', NULL, 1),
(5607913, 812001, 106349, '<td valign="top">Like the colors in this (a purple wall??)</td>', 'Like the colors in this (a purple wall??)', '2009-08-11 21:06:05.000000', NULL, 1),
(5607916, 811750, 57447, '<td valign="top">Nice composition, meets challenge.  Time to bump up a score for good title.</td>', 'Nice composition, meets challenge.  Time to bump up a score for good title.', '2009-08-11 21:23:29.000000', NULL, 1),
(5607967, 812013, 61679, '<td valign="top">Back to comment and bump: I agree that the nose is square but it doesn''t speak to me as the strongest subject in this image.  If the eyes were less buggy looking, that would be the main subject.  But since they are a little uncomfortable to stare at (Pun intended), the leading lines of the face bring my attention down to the nose.  But the nose in itself is not that compelling and my eyes wander off to other areas in the photo.  I love the post processing you did.</td>', 'Back to comment and bump: I agree that the nose is square but it doesn''t speak to me as the strongest subject in this image.  If the eyes were less buggy looking, that would be the main subject.  But since they are a little uncomfortable to stare at (Pun intended), the leading lines of the face bring my attention down to the nose.  But the nose in itself is not that compelling and my eyes wander off to other areas in the photo.  I love the post processing you did.', '2009-08-11 22:16:48.000000', NULL, 1),
(5608082, 810662, 50695, '<td valign="top">compelling blur.</td>', 'compelling blur.', '2009-08-11 23:24:01.000000', NULL, 1),
