(5608298, 811876, 72103, '<td valign="top">Excellent, great shot, congrats........!</td>', 'Excellent, great shot, congrats........!', '2009-08-12 01:02:26.000000', NULL, 0),
(5608307, 811893, 31535, '<td valign="top">Great image. Congratz on your first ribbon.</td>', 'Great image. Congratz on your first ribbon.', '2009-08-12 01:05:23.000000', NULL, 0),
(5608308, 811893, 72103, '<td valign="top">OK, so first and second same spot...........Never seen that before.  Both excellent, I like additional perspective on this one....  Congrats!</td>', 'OK, so first and second same spot...........Never seen that before.  Both excellent, I like additional perspective on this one....  Congrats!', '2009-08-12 01:05:32.000000', NULL, 0),
