(5608312, 811876, 73564, '<td valign="top">I bumped you to a 7 before roll over, nice take. Congrats!</td>', 'I bumped you to a 7 before roll over, nice take. Congrats!', '2009-08-12 01:06:48.000000', NULL, 0),
(5608314, 811693, 73564, '<td valign="top">Congrats, 7 from me.</td>', 'Congrats, 7 from me.', '2009-08-12 01:07:13.000000', NULL, 0),
