(5608317, 811876, 31535, '<td valign="top">LOL, blue and red ribbons of the same skylight. Congratz on the red.</td>', 'LOL, blue and red ribbons of the same skylight. Congratz on the red.', '2009-08-12 01:07:26.000000', NULL, 0),
(5608330, 811876, 67697, '<td valign="top">Andrew - this is cool.  It''s like a depth of perception puzzle.  Very striking.  Congrats on the red!</td>', 'Andrew - this is cool.  It''s like a depth of perception puzzle.  Very striking.  Congrats on the red!', '2009-08-12 01:11:23.000000', NULL, 0),
(5608334, 811390, 50695, '<td valign="top">energetic concentric squares. a sizzling execution of the challenge. sorry I only gave it a 6. I was stingy.</td>', 'energetic concentric squares. a sizzling execution of the challenge. sorry I only gave it a 6. I was stingy.', '2009-08-12 01:12:36.000000', NULL, 0),
(5608337, 811849, 50695, '<td valign="top">Great title. I feel the thinking on the board. I only gave this a 6. Underrated!</td>', 'Great title. I feel the thinking on the board. I only gave this a 6. Underrated!', '2009-08-12 01:13:50.000000', NULL, 0),
(5608357, 811952, 83313, '<td valign="top">Congrats on a nice high score, and what I think is a new PB for you!</td>', 'Congrats on a nice high score, and what I think is a new PB for you!', '2009-08-12 01:18:30.000000', NULL, 0),
(5608362, 811877, 7889, '<td valign="top">Well the border is distinct and recognisable to me. DQ? mmmmm<br/><br/><i>Message edited by author 2009-08-12 00:21:13.</i></td>', 'Well the border is distinct and recognisable to me. DQ? mmmmm', '2009-08-12 01:20:46.000000', '2009-08-12 01:21:13.000000', 0),
(5608368, 812013, 83313, '<td valign="top">You came in very close to where my circle entry did and probably for the same reason: The required shape was not a prominent enough feature in the eyes of many voters. I gave this an 8, however.</td>', 'You came in very close to where my circle entry did and probably for the same reason: The required shape was not a prominent enough feature in the eyes of many voters. I gave this an 8, however.', '2009-08-12 01:23:31.000000', NULL, 0),
(5608375, 811693, 52549, '<td valign="top">Oh, I LOVE this. What a fantastic abstract. Thanks goodness it ribboned for you, Eric AND it''s your first ribbon, too! Congratulations.</td>', 'Oh, I LOVE this. What a fantastic abstract. Thanks goodness it ribboned for you, Eric AND it''s your first ribbon, too! Congratulations.', '2009-08-12 01:26:05.000000', NULL, 0),
(5608379, 811876, 52549, '<td valign="top">Excellent shot, Andrew. Congrats on your ribbon!</td>', 'Excellent shot, Andrew. Congrats on your ribbon!', '2009-08-12 01:27:53.000000', NULL, 0),
(5608381, 811877, 83313, '<td valign="top">Ouch! It sure looks like a distinct border to me! I gave it a 9, if that is any consolation.</td>', 'Ouch! It sure looks like a distinct border to me! I gave it a 9, if that is any consolation.', '2009-08-12 01:28:20.000000', NULL, 0),
(5608384, 811893, 52549, '<td valign="top">Congrats on your first ribbon and new PB, Lian. Wonderful shot, love the perspective.</td>', 'Congrats on your first ribbon and new PB, Lian. Wonderful shot, love the perspective.', '2009-08-12 01:29:27.000000', NULL, 0),
(5608385, 812043, 30490, '<td valign="top">hmmm reading your photographer comments now, I never even noticed the footprints you mention.  I think this image had potential, but suffered from a bad perspective and needed cropping.  Just my two cents, you might like it just the way it is...</td>', 'hmmm reading your photographer comments now, I never even noticed the footprints you mention.  I think this image had potential, but suffered from a bad perspective and needed cropping.  Just my two cents, you might like it just the way it is...', '2009-08-12 01:29:32.000000', NULL, 0),
(5608397, 811893, 81782, '<td valign="top">Wow... hearty congratulations on ribbon mate! Damn, i walk below this hundred times a day (i work in Millenia Towers) and never cared to look up and see such a beautiful sight.. very well done.. congrats once again.</td>', 'Wow... hearty congratulations on ribbon mate! Damn, i walk below this hundred times a day (i work in Millenia Towers) and never cared to look up and see such a beautiful sight.. very well done.. congrats once again.', '2009-08-12 01:34:07.000000', NULL, 0),
(5608398, 811529, 83313, '<td valign="top">Don''t blame me, I gave it a 6! Put away that cluebat!</td>', 'Don''t blame me, I gave it a 6! Put away that cluebat!', '2009-08-12 01:34:10.000000', NULL, 0),
